{"kind":"tool","id":"psIY7eJBSp4","toolName":"write_file","input":{"path":"backend/src/application/sensors/service.py","instructions":"Add the application service that resolves creators and delegates persistence.","content":"from infrastructure.persistence.device_repository import DeviceRepository

from domain.sensors.creators import get_creator
from domain.sensors.entity import Sensor


class SensorService:
    def __init__(self, repository: DeviceRepository) -> None:
        self._repository = repository

    def create_sensor(self, sensor_type: str, display_name: str | None = None) -> Sensor:
        creator = get_creator(sensor_type)
        sensor = creator.create_sensor(display_name=display_name)
        return self._repository.save_sensor(sensor)

    def list_sensors(self) -> list[Sensor]:
        return self._repository.list_sensors()
"}}
