{"kind":"tool","id":"psKdto_JMBQ","toolName":"write_file","input":{"path":"backend/alembic/env.py","instructions":"Wire Alembic autogeneration to the persistence metadata and models.","content":"import sys
from logging.config import fileConfig
from pathlib import Path

from alembic import context
from sqlalchemy import engine_from_config, pool

BASE_DIR = Path(__file__).resolve().parents[1]
SRC_DIR = BASE_DIR / "src"
sys.path.insert(0, str(SRC_DIR))

from infrastructure.persistence.base import Base  # noqa: E402
from infrastructure.persistence import models  # noqa: F401,E402
from infrastructure.settings import settings  # noqa: E402

config = context.config

if config.config_file_name is not None:
    fileConfig(config.config_file_name)

config.set_main_option("sqlalchemy.url", settings.database_url)
target_metadata = Base.metadata


def run_migrations_offline() -> None:
    url = config.get_main_option("sqlalchemy.url")
    context.configure(
        url=url,
        target_metadata=target_metadata,
        literal_binds=True,
        dialect_opts={"paramstyle": "named"},
    )
    with context.begin_transaction():
        context.run_migrations()


def run_migrations_online() -> None:
    connectable = engine_from_config(
        config.get_section(config.config_ini_section, {}),
        prefix="sqlalchemy.",
        poolclass=pool.NullPool,
    )
    with connectable.connect() as connection:
        context.configure(connection=connection, target_metadata=target_metadata)
        with context.begin_transaction():
            context.run_migrations()


if context.is_offline_mode():
    run_migrations_offline()
else:
    run_migrations_online()
"}}


{"kind":"tool","id":"psK81J36r6E","toolName":"write_file","input":{"path":"frontend/src/features/sensors/SensorList.tsx","instructions":"Add the dashboard sensor list and create controls.","content":"import { useEffect, useState } from "react";
import { createSensor, fetchSensors, type SensorDto } from "../../services/api";

export function SensorList() {
  const [sensors, setSensors] = useState<SensorDto[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [creating, setCreating] = useState<string | null>(null);

  async function loadSensors() {
    try {
      setError(null);
      setSensors(await fetchSensors());
    } catch {
      setError("Unable to load sensors. Check that the API is running.");
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    void loadSensors();
  }, []);

  async function handleCreate(type: "moisture" | "light") {
    try {
      setCreating(type);
      setError(null);
      await createSensor(type);
      await loadSensors();
    } catch {
      setError("Unable to create the sensor.");
    } finally {
      setCreating(null);
    }
  }

  return (
    <div className="mt-4 rounded-lg bg-slate-50 p-4">
      <div className="mb-4 flex flex-wrap gap-2">
        <button
          type="button"
          onClick={() => void handleCreate("moisture")}
          disabled={creating !== null}
          className="rounded-md bg-emerald-600 px-3 py-2 text-sm font-medium text-white hover:bg-emerald-700 disabled:opacity-50"
        >
          {creating === "moisture" ? "Adding…" : "Add moisture sensor"}
        </button>
        <button
          type="button"
          onClick={() => void handleCreate("light")}
          disabled={creating !== null}
          className="rounded-md bg-sky-600 px-3 py-2 text-sm font-medium text-white hover:bg-sky-700 disabled:opacity-50"
        >
          {creating === "light" ? "Adding…" : "Add light sensor"}
        </button>
      </div>
      {error && <p className="mb-3 text-sm text-red-600">{error}</p>}
      {loading ? (
        <p className="text-sm text-slate-500">Loading sensors…</p>
      ) : sensors.length === 0 ? (
        <p className="text-sm text-slate-500">No sensors yet. Add one above.</p>
      ) : (
        <ul className="space-y-2">
          {sensors.map((sensor) => (
            <li key={sensor.id} className="rounded-md border border-slate-200 bg-white p-3">
              <p className="font-medium text-slate-800">{sensor.display_name}</p>
              <p className="text-xs text-slate-500">{sensor.device_type}</p>
              <pre className="mt-2 overflow-x-auto text-xs text-slate-600">
                {JSON.stringify(sensor.default_config, null, 2)}
              </pre>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
"}}
{"kind":"tool","id":"psLBITh8YaM","toolName":"write_file","input":{"path":"frontend/src/services/api.ts","instructions":"Extend the API client with typed sensor list and create functions.","content":"export type HealthResponse = { status: string; db: "ok" | "fail" };

export type SensorDto = {
  id: string;
  device_type: string;
  display_name: string;
  default_config: Record<string, unknown>;
};

const apiBaseUrl = import.meta.env.VITE_API_BASE_URL ?? "";

async function request<T>(path: string, options?: RequestInit): Promise<T> {
  const response = await fetch(`${apiBaseUrl}${path}`, {
    ...options,
    headers: { "Content-Type": "application/json", ...options?.headers },
  });
  if (!response.ok) {
    throw new Error(`Request failed: ${response.status}`);
  }
  return response.json() as Promise<T>;
}

export function fetchHealth(): Promise<HealthResponse> {
  return request<HealthResponse>("/health");
}

export function fetchSensors(): Promise<SensorDto[]> {
  return request<SensorDto[]>("/api/sensors");
}

export function createSensor(type: "moisture" | "light", displayName?: string): Promise<SensorDto> {
  return request<SensorDto>("/api/sensors", {
    method: "POST",
    body: JSON.stringify({ type, display_name: displayName ?? null }),
  });
}
"}}
