{"kind":"tool","id":"7mk8bfGXzJY","toolName":"write_file","input":{"path":"backend/src/infrastructure/persistence/location_repository.py","instructions":"Persist and retrieve location plus zones atomically using SQLAlchemy transactions.","content":"from uuid import UUID

from sqlalchemy import select
from sqlalchemy.orm import Session

from domain.locations.entity import LocationConfig

from .models import LocationRow, ZoneRow


class LocationRepository:
    def __init__(self, session: Session) -> None:
        self._session = session

    def save_config(self, config: LocationConfig) -> tuple[LocationRow, list[ZoneRow]]:
        location_row = LocationRow(name=config.location.name)
        try:
            self._session.add(location_row)
            self._session.flush()
            zone_rows = [
                ZoneRow(
                    location_id=location_row.id,
                    name=zone.name,
                    moisture_threshold_low=zone.moisture_threshold_low,
                    moisture_threshold_high=zone.moisture_threshold_high,
                    schedule=dict(zone.schedule),
                )
                for zone in config.location.zones
            ]
            self._session.add_all(zone_rows)
            self._session.flush()
            self._session.commit()
        except Exception:
            self._session.rollback()
            raise

        for zone_row in zone_rows:
            self._session.refresh(zone_row)
        self._session.refresh(location_row)
        return location_row, zone_rows

    def get_config(self, location_id: UUID) -> tuple[LocationRow, list[ZoneRow]] | None:
        location_row = self._session.get(LocationRow, location_id)
        if location_row is None:
            return None
        zone_rows = self._session.scalars(
            select(ZoneRow)
            .where(ZoneRow.location_id == location_id)
            .order_by(ZoneRow.name, ZoneRow.id)
        ).all()
        return location_row, list(zone_rows)
